o:[{hi:'462 cm²',en:'462 cm²'},{hi:'308 cm²',en:'308 cm²'},{hi:'616 cm²',en:'616 cm²'},{hi:'154 cm²',en:'154 cm²'}],d:2,a:0,src:{hi:'RRB NTPC 2021',en:'RRB NTPC 2021'},
